
.attr-bar {
  padding: 10px 12px;
  background: rgba(255, 255, 255, 0.4);
  border-bottom: 1px solid var(--c-mist);
}

.character-info {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 10px;
  padding-bottom: 8px;
  border-bottom: 1px dashed var(--c-mist);
}

.char-name {
  font-family: var(--font-kai);
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--c-ink);
}

.char-identity {
  font-size: 0.75rem;
  color: var(--c-bronze);
  padding: 2px 6px;
  background: rgba(139, 105, 20, 0.1);
  border-radius: 2px;
}

.char-age {
  font-size: 0.7rem;
  color: var(--c-cloud);
  margin-left: auto;
}

.attrs-mini {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin-bottom: 10px;
}

.attr-mini {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px 6px;
  background: rgba(255, 255, 255, 0.6);
  border: 1px solid var(--c-mist);
  border-left: 3px solid var(--attr-color);
  border-radius: 2px;
  font-size: 0.72rem;

  .attr-icon {
    font-size: 0.85rem;
  }

  .attr-name {
    color: var(--c-cloud);
    min-width: 2em;
  }

  .attr-value {
    font-weight: 600;
    color: var(--c-ink);
  }

  .attr-tier {
    font-family: var(--font-kai);
    font-size: 0.65rem;
    color: var(--attr-color);
    margin-left: auto;
    padding: 1px 4px;
    background: rgba(0, 0, 0, 0.05);
    border-radius: 2px;
  }
}

.wealth-row {
  display: flex;
  justify-content: center;
  gap: 16px;
}

.wealth-item {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 0.75rem;
  font-weight: 600;

  i {
    font-size: 0.6rem;
  }

  &.gold {
    color: #d4af37;
  }

  &.silver {
    color: #8b8b8b;

    i {
      font-size: 0.5rem;
    }
  }

  &.copper {
    color: #b87333;

    i {
      font-size: 0.4rem;
    }
  }
}

@media (max-width: 500px) {
  .attrs-mini {
    grid-template-columns: repeat(2, 1fr);
  }
}
