
.attire-panel {
  display: flex;
  flex-direction: column;
}

.attire-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}

.attire-card {
  background: rgba(255, 255, 255, 0.7);
  border: 1px solid var(--c-mist);
  border-radius: 4px;
  padding: 10px;
  position: relative;

  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    border-radius: 4px 4px 0 0;
  }

  &.main::before {
    background: linear-gradient(90deg, #e34234, #d4af37);
  }
  &.inner::before {
    background: linear-gradient(90deg, #ff9a9e, #fad0c4);
  }
  &.hosiery::before {
    background: linear-gradient(90deg, #a18cd1, #fbc2eb);
  }
  &.shoes::before {
    background: linear-gradient(90deg, #8b6914, #d4af37);
  }
}

.attire-label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.7rem;
  color: var(--c-cloud);
  margin-bottom: 6px;

  i {
    font-size: 0.75rem;
  }
}

.attire-type {
  font-family: var(--font-kai);
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--c-ink);
  margin-bottom: 4px;
}

.attire-desc {
  font-size: 0.72rem;
  color: var(--c-cloud);
  line-height: 1.4;
  margin-bottom: 6px;
}

.attire-quality {
  font-size: 0.65rem;
  padding: 2px 6px;
  background: rgba(139, 105, 20, 0.1);
  color: var(--c-bronze);
  border-radius: 2px;
  display: inline-block;
}

.accessory-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
}

.accessory-item {
  display: flex;
  flex-direction: column;
  padding: 8px;
  background: rgba(255, 255, 255, 0.5);
  border: 1px solid var(--c-mist);
  border-radius: 4px;
}

.acc-name {
  font-size: 0.7rem;
  color: var(--c-cloud);
  margin-bottom: 4px;
}

.acc-value {
  font-size: 0.8rem;
  color: var(--c-ink);
  line-height: 1.4;
}

@media (max-width: 500px) {
  .attire-grid,
  .accessory-grid {
    grid-template-columns: 1fr;
  }
}
