
.tianyan-card {
  width: 100%;
  max-width: 720px;
  background: linear-gradient(135deg, var(--c-paper) 0%, var(--c-parchment) 100%);
  border: 2px solid var(--c-bronze);
  border-radius: 4px;
  box-shadow:
    0 4px 20px rgba(44, 36, 22, 0.15),
    inset 0 1px 0 rgba(255, 255, 255, 0.5);
  display: flex;
  flex-direction: column;
  font-family: var(--font-song);
  color: var(--c-ink);
  font-size: 13px;
  line-height: 1.5;
  margin: 0 auto;
  overflow: hidden;
  position: relative;
}

/* 顶部装饰 */
.header-ornament {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8px 0;
  background: linear-gradient(90deg, transparent 0%, var(--c-mist) 50%, transparent 100%);
}

.ornament-line {
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--c-bronze), transparent);
  max-width: 100px;
}

.ornament-icon {
  font-size: 1.2rem;
  color: var(--c-gold);
  margin: 0 12px;
  text-shadow: 0 1px 2px rgba(212, 175, 55, 0.3);
}

/* 内容区域 */
.content-area {
  padding: 12px;
  min-height: 0;
  background: rgba(255, 255, 255, 0.3);
}

.tab-pane {
  animation: fadeIn 0.3s ease;
}

/* 过渡动画 */
.fade-enter-active,
.fade-leave-active {
  transition: all 0.25s ease;
}

.fade-enter-from,
.fade-leave-to {
  opacity: 0;
  transform: translateY(6px);
}

/* 底部装饰 */
.footer-ornament {
  padding: 6px;
  text-align: center;
  background: linear-gradient(90deg, transparent 0%, var(--c-mist) 50%, transparent 100%);
  border-top: 1px solid var(--c-mist);
}

.footer-text {
  font-family: var(--font-kai);
  font-size: 0.75rem;
  color: var(--c-cloud);
  letter-spacing: 0.2em;
}
