
.attr-panel {
  display: flex;
  flex-direction: column;
}

.attr-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}

.attr-card {
  background: rgba(255, 255, 255, 0.7);
  border: 1px solid var(--c-mist);
  border-radius: 4px;
  padding: 10px;
  position: relative;
  overflow: hidden;

  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: var(--attr-color);
  }
}

.attr-header {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 8px;

  .attr-icon {
    font-size: 1rem;
  }

  .attr-name {
    font-family: var(--font-kai);
    font-size: 0.9rem;
    font-weight: 600;
    color: var(--c-ink);
  }

  .attr-tier-badge {
    margin-left: auto;
    font-family: var(--font-kai);
    font-size: 0.7rem;
    color: white;
    background: var(--attr-color);
    padding: 2px 6px;
    border-radius: 2px;
  }
}

.attr-progress {
  margin-bottom: 6px;
}

.progress-track {
  height: 8px;
  background: var(--c-parchment);
  border: 1px solid var(--c-mist);
  border-radius: 4px;
  position: relative;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--attr-color) 0%, var(--attr-color) 100%);
  transition: width 0.3s ease;
}

.progress-markers {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;

  .marker {
    position: absolute;
    top: 0;
    bottom: 0;
    width: 1px;
    background: rgba(0, 0, 0, 0.15);
  }
}

.progress-info {
  display: flex;
  justify-content: flex-end;
  margin-top: 2px;
  font-size: 0.65rem;

  .value-current {
    color: var(--c-ink);
    font-weight: 600;
  }

  .value-max {
    color: var(--c-cloud);
  }
}

.attr-desc {
  font-size: 0.7rem;
  color: var(--c-cloud);
  margin-bottom: 6px;
  line-height: 1.3;
}

.attr-controls {
  display: flex;
  justify-content: flex-end;
  gap: 4px;
}

.ctrl-btn {
  width: 22px;
  height: 22px;
  border: 1px solid var(--c-mist);
  border-radius: 2px;
  background: var(--c-paper);
  color: var(--c-cloud);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.6rem;
  transition: all 0.2s;

  &:hover:not(:disabled) {
    background: var(--attr-color);
    color: white;
    border-color: var(--attr-color);
  }

  &:disabled {
    opacity: 0.4;
    cursor: not-allowed;
  }

  &.plus:hover:not(:disabled) {
    background: var(--c-jade);
    border-color: var(--c-jade);
  }

  &.minus:hover:not(:disabled) {
    background: var(--c-vermilion);
    border-color: var(--c-vermilion);
  }
}

.reputation-grid {
  display: grid;
  gap: 8px;
}

.rep-item {
  display: flex;
  align-items: center;
  gap: 8px;
}

.rep-name {
  font-size: 0.75rem;
  color: var(--c-ink);
  min-width: 5em;
}

.rep-bar {
  flex: 1;
  height: 6px;
  background: var(--c-parchment);
  border: 1px solid var(--c-mist);
  border-radius: 3px;
  overflow: hidden;
}

.rep-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--c-jade) 0%, var(--c-gold) 100%);
  transition: width 0.3s ease;
}

.rep-value {
  font-size: 0.7rem;
  color: var(--c-bronze);
  font-weight: 600;
  min-width: 2em;
  text-align: right;
}

@media (max-width: 500px) {
  .attr-grid {
    grid-template-columns: 1fr;
  }
}
